+      reason: 'knn as query added in 8.12'
+
+  - do:
+      indices.create:
+        index: my_index
+        body:
+          settings:
+            number_of_shards: 1
+          mappings:
+            dynamic: false
+            properties:
+              my_vector:
+                type: dense_vector
+                dims: 4
+                index : true
+                similarity : l2_norm
+              my_name:
+                type: keyword
+                store: true
+          aliases:
+            my_alias:
+              filter:
+                term:
+                  my_name: v2
+            my_alias1:
+              filter:
+                term:
+                  my_name: v1
+
+  - do:
+      bulk:
+        refresh: true
+        index: my_index
+        body:
+          - '{"index": {"_id": "1"}}'
+          - '{"my_vector": [1, 1, 1, 1], "my_name": "v1"}'
+          - '{"index": {"_id": "2"}}'
+          - '{"my_vector": [1, 1, 1, 2], "my_name": "v2"}'
+          - '{"index": {"_id": "3"}}'
+          - '{"my_vector": [1, 1, 1, 3], "my_name": "v1"}'
